ListNode removeElements(ListNode head, int val) {
    ListNode dummy = new ListNode(0, head);
    ListNode prev = dummy;
    while (prev.next != null) {
        if (prev.next.val == val) prev.next = prev.next.next; // skip
        else prev = prev.next;
    }
    return dummy.next;   // real head, even if original head was removed
}

ListNode reverse(ListNode head) {
    ListNode prev = null, curr = head;
    while (curr != null) {
        ListNode nxt = curr.next; // save
        curr.next = prev;         // flip
        prev = curr;              // advance
        curr = nxt;
    }
    return prev;
}

def merge_two(l1, l2):
    dummy = tail = ListNode(0)
    while l1 and l2:
        if l1.val <= l2.val:
            tail.next, l1 = l1, l1.next
        else:
            tail.next, l2 = l2, l2.next
        tail = tail.next
    tail.next = l1 or l2     # attach the leftover
    return dummy.next
